<h2>Calculate molecular weight from a chemical formula</h2><p class="lead">Parse a chemical formula with element symbols, parentheses and hydrate dots to estimate average molar mass.</p><div class="notice">The parser supports element symbols, integer subscripts, parentheses and dot/hydrate coefficients such as CuSO4.5H2O. It does not interpret charges or isotope notation.</div><div class="form-grid"><div class="field"><label for="formula">Chemical formula</label><input id="formula" type="text" value="CuSO4.5H2O" placeholder="e.g. C6H12O6 or CuSO4.5H2O"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Molecular / formula weight</span><strong id="mwout">—</strong></div><div class="metric"><span>Total atoms in formula</span><strong id="atoms">—</strong></div><div class="metric"><span>Distinct elements</span><strong id="elements">—</strong></div><div class="metric"><span>Parsed formula</span><strong id="normalized">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
