function clear(){$('mwout').textContent='—';$('atoms').textContent='—';$('elements').textContent='—';$('normalized').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const weights={H:1.008,He:4.002602,Li:6.94,Be:9.0121831,B:10.81,C:12.011,N:14.007,O:15.999,F:18.998403163,Ne:20.1797,Na:22.98976928,Mg:24.305,Al:26.9815385,Si:28.085,P:30.973761998,S:32.06,Cl:35.45,Ar:39.948,K:39.0983,Ca:40.078,Sc:44.955908,Ti:47.867,V:50.9415,Cr:51.9961,Mn:54.938044,Fe:55.845,Co:58.933194,Ni:58.6934,Cu:63.546,Zn:65.38,Ga:69.723,Ge:72.630,As:74.921595,Se:78.971,Br:79.904,Kr:83.798,Rb:85.4678,Sr:87.62,Y:88.90584,Zr:91.224,Nb:92.90637,Mo:95.95,Ru:101.07,Rh:102.9055,Pd:106.42,Ag:107.8682,Cd:112.414,In:114.818,Sn:118.710,Sb:121.760,Te:127.60,I:126.90447,Xe:131.293,Cs:132.90545196,Ba:137.327,La:138.90547,Ce:140.116,Pr:140.90766,Nd:144.242,Sm:150.36,Eu:151.964,Gd:157.25,Tb:158.92535,Dy:162.500,Ho:164.93033,Er:167.259,Tm:168.93422,Yb:173.045,Lu:174.9668,Hf:178.49,Ta:180.94788,W:183.84,Re:186.207,Os:190.23,Ir:192.217,Pt:195.084,Au:196.966569,Hg:200.592,Tl:204.38,Pb:207.2,Bi:208.98040,Th:232.0377,U:238.02891};function parseSimple(str){let i=0;function group(){const counts={};while(i<str.length&&str[i]!==')'){if(str[i]==='('){i++;const sub=group();if(str[i]!==')')throw 0;i++;let ds='';while(/\d/.test(str[i]||'')){ds+=str[i++]}const mult=ds?+ds:1;for(const [e,c] of Object.entries(sub))counts[e]=(counts[e]||0)+c*mult}else{const m=str.slice(i).match(/^([A-Z][a-z]?)/);if(!m||!weights[m[1]])throw 0;const e=m[1];i+=e.length;let ds='';while(/\d/.test(str[i]||'')){ds+=str[i++]}counts[e]=(counts[e]||0)+(ds?+ds:1)}}return counts}const c=group();if(i!==str.length)throw 0;return c}const raw=$('formula').value.trim().replace(/·/g,'.');if(!raw)throw 0;const total={};for(const part0 of raw.split('.')){if(!part0)continue;let part=part0,mult=1;const m=part.match(/^(\d+)(.*)$/);if(m){mult=+m[1];part=m[2]}const c=parseSimple(part);for(const [e,n] of Object.entries(c))total[e]=(total[e]||0)+n*mult}let mw=0,atoms=0;for(const [e,n] of Object.entries(total)){mw+=weights[e]*n;atoms+=n}$('mwout').textContent=fmt(mw,6)+' g/mol';$('atoms').textContent=fmt(atoms